import subprocess, sys, time, json, urllib.request, urllib.error

def req(method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(f'http://127.0.0.1:8033{path}', data=data, method=method)
    if data is not None:
        r.add_header('Content-Type', 'application/json')
    try:
        with urllib.request.urlopen(r, timeout=3) as resp:
            payload = resp.read()
            return resp.status, (json.loads(payload) if payload else None)
    except urllib.error.HTTPError as e:
        payload = e.read()
        try:
            parsed = json.loads(payload) if payload else None
        except json.JSONDecodeError:
            parsed = None
        return e.code, parsed

subprocess.run(['go', 'build', '-o', 'app_bin', '.'], check=True)
srv = subprocess.Popen(['./app_bin'])
try:
    ok = False
    status = body = None
    for _ in range(30):
        try:
            status, body = req('POST', '/register', {'username': 'al', 'password': 'secret'})
            ok = True
            break
        except (urllib.error.URLError, ConnectionResetError):
            time.sleep(0.5)
    assert ok, 'server never became reachable on :8033'
    assert status == 200, f'expected 200 for valid request, got {status} body={body!r}'
    assert body.get('initial') == 'a', f'unexpected body: {body!r}'

    status, body = req('POST', '/register', {'password': 'secret'})
    assert status == 400, f'expected 400 for missing username, got {status} body={body!r}'

    status, body = req('POST', '/register', {'username': '', 'password': 'secret'})
    assert status == 400, f'expected 400 for empty username, got {status} body={body!r}'
finally:
    srv.terminate()
    try:
        srv.wait(timeout=5)
    except Exception:
        srv.kill()
